<style>
@property --progress {
  syntax: "<number>";
  inherits: true;
  initial-value: 0;
}

.scene {
  animation: progress 20s linear infinite;
}

@keyframes progress {
  from {
    --progress: 0;
  }
  to {
    --progress: 1;
  }
}

.walker {
  position: absolute;
  bottom: 0;
  width: 12%;
  left: calc(var(--progress) * 112% - 12%);
}

.flat {
  clip-path: inset(0 0 0 calc(100% - (var(--progress) * 112%)));
}
.bushy {
  clip-path: inset(0 calc(var(--progress) * 112%) 0 0);
}
.transition-bushy {
  clip-path: inset(
    calc((1 - min(1, max(0, (var(--progress) - 0.80) / 0.20))) * 100%)
    0
    0
    0
  );
}
</style>
